--
-- Table structure for table `facturacion`
--

DROP TABLE IF EXISTS `facturacion`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `facturacion` (
  `ID_Facturacion` int(8) NOT NULL auto_increment,
  `Nombre_Empresa` varchar(50) default NULL,
  `Rut_Empresa` varchar(15) default NULL,
  `Nro_Cotizacion` varchar(50) default NULL,
  `Fecha_Cotizacion` date default NULL,
  `Situacion_Cotizacion` int(11) default NULL,
  `Nro_Orden_Compra` varchar(50) default NULL,
  `Fecha_Orden_Compra` date default NULL,
  `Situacion_Orden_Compra` int(11) default NULL,
  `Nro_Factura` int(8) default NULL,
  `Fecha_Factura` date default NULL,
  `Situacion_Factura` int(11) default NULL,
  `Tipo_Moneda` int(11) default NULL,
  `Monto` decimal(19,2) default NULL,
  `Vendedor` varchar(15) default NULL,
  `Nombre_Contacto` varchar(50) default NULL,
  `Correo_Contacto` varchar(50) default NULL,
  `Telefono_Contacto` int(12) default NULL,
  `Direccion` varchar(100) default NULL,
  `Detalle` varchar(200) default NULL,
  PRIMARY KEY  (`ID_Facturacion`)
) ENGINE=MyISAM AUTO_INCREMENT=92 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

