  `Valor` decimal(19,2) default NULL,
  `Fecha_Ingreso` date NOT NULL,
  `Descripción` varchar(200) default NULL,
  `Lugar` varchar(50) default NULL,
  `Encargado_Ingreso` varchar(50) NOT NULL,
  `Encargado_Control` varchar(50) default NULL,
  `Fecha_Control` date NOT NULL,
  PRIMARY KEY  (`ID_Inv`)
) ENGINE=MyISAM AUTO_INCREMENT=3304 DEFAULT CHARSET=latin1;
