DROP TABLE IF EXISTS `inventario_usado`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `inventario_usado` (
  `ID_Inv` int(5) NOT NULL,
  `Tipo_Guia` varchar(4) default NULL,
  `Guia_Despacho` int(8) default NULL,
  `Guia_Despacho_Retiro` int(8) default NULL,
  `Factura_Venta` int(8) default NULL,
  `Nro_Serie` varchar(50) default NULL,
  `Nombre` varchar(50) default NULL,
  `Categoria` varchar(50) default NULL,
  `Marca` varchar(45) default NULL,
  `Tipo_Moneda` varchar(50) default NULL,
  `Valor` decimal(19,2) default NULL,
  `Fecha_Ingreso` date default NULL,
  `Descripción` varchar(200) default NULL,
  `Lugar` varchar(50) default NULL,
  `Encargado_Ingreso` varchar(50) default NULL,
  `Encargado_Control` varchar(50) default NULL,
  `Fecha_Control` date default NULL,
  `Fecha_Salida` date default NULL,
  `Encargado_Salida` varchar(50) default NULL,
  `Cliente` varchar(50) default NULL,
  PRIMARY KEY  (`ID_Inv`)
) ENGINE=MyISAM DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

