--
-- Table structure for table `tbtickets`
--

DROP TABLE IF EXISTS `tbtickets`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `tbtickets` (
  `idtbtickets` int(11) NOT NULL auto_increment,
  `id_ticket` varchar(60) NOT NULL,
  `tipo` int(1) NOT NULL COMMENT '1: Interno // 2:Externo',
  `estado` int(1) NOT NULL default '0' COMMENT '0:Abierto, 1:En Revision, 2:Cerrado',
  `fecha_creacion` timestamp NULL default CURRENT_TIMESTAMP,
  `fecha_revision` timestamp NULL default NULL,
  `fecha_cierre` timestamp NULL default NULL,
  `id_cliente` int(3) default NULL,
  `nombre_cliente` varchar(100) default NULL,
  `nombre_contacto` varchar(100) default NULL,
  `telef_contacto` varchar(20) default NULL,
  `movil_contacto` varchar(20) default NULL,
  `email_contacto` varchar(45) default NULL,
  `direccion_contacto` varchar(100) default NULL,
  `id_terminal` int(3) default NULL,
  `modelo_terminal` varchar(45) default NULL,
  `nserie_terminal` varchar(100) default NULL,
  `nserie_falla` varchar(100) default NULL,
  `detalle_falla` varchar(300) default NULL,
  `detalle_interno` varchar(300) default NULL,
  `asignado` varchar(45) default NULL,
  `usuario` varchar(45) default NULL,
  PRIMARY KEY  (`idtbtickets`),
  KEY `idx_id_tickets` (`id_ticket`)
) ENGINE=MyISAM AUTO_INCREMENT=166 DEFAULT CHARSET=utf8 COMMENT='Info Tickets creados';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `tbtickets`
--

LOCK TABLES `tbtickets` WRITE;
/*!40000 ALTER TABLE `tbtickets` DISABLE KEYS */;
INSERT INTO `tbtickets` VALUES (1,'TMC-INC1',1,2,'2013-09-03 22:07:43',NULL,'2013-09-03 21:27:56',1,'Defensoría Penal Pública','Clauss Fridman R.','24238149','75390409','cfridman@entel.cl','Amunategui 20, piso 2 CNT, Santiago – Chile',0,'HDX 7000','00000000000000','00000000000000','Cliente informa que RMX arroja alarma',NULL,NULL,'soporte'),(2,'TMC-INC2',1,2,'2013-09-03 22:07:10',NULL,'2013-09-03 21:55:41',1,'Defensoría Penal Pública','Clauss Fridman R.','24238149','75390409','cfridman@entel.cl','Amunategui 20, piso 2 CNT, Santiago – Chile',0,'RSS 4000','00000','00000','Cliente informa problemas con RSS 4000, no permite ingreso.\n',NULL,NULL,'soporte'),(3,'TMC-INC3',1,2,'2013-09-03 22:10:00','2013-09-03 21:47:14','2013-09-05 20:33:27',1,'Defensoría Penal Pública','Clauss Fridman R.','24238149','75390409','fcifuentes@touchmedia.cl','Amunategui 20, piso 2 CNT, Santiago – Chile',0,'HDX 7000','00000000000001','00000000000001','Cliente informa problemas para ingresar a servidor de Streaming.','Equipo en arriendo temporal perdio comunicación, se realiza restablecimiento del ssitema con lo cual se soluciono el problema.',NULL,'soporte'),(4,'TMC-INC4',1,2,'2013-09-03 22:12:21',NULL,'2013-09-03 21:56:10',1,'Defensoría Penal Pública','Clauss Fridman R.','24238149','75390409','fcifuentes@touchmedia.cl','Amunategui 20, piso 2 CNT, Santiago – Chile',0,'RMX','00000000000002','00000000000002','Cliente informa problemas para generar multiconferencias con la MCU.',NULL,NULL,'soporte'),(5,'TMC-INC5',1,2,'2013-09-03 22:10:11',NULL,'2013-09-03 21:47:48',1,'Defensoría Penal Pública','Clauss Fridman R.','24238149','75390409','chernandez@touchmedia.cl','Amunategui 20, piso 2 CNT, Santiago – Chile',0,'indefinido','00000','00000','INC000002914257\nFecha de creacion 22/11/2012\nFecha de atencion 26/11/2012\n\nFalla: Usuario Indica que equipo se reinicia cada vez que intenta conectarse.\n\nObs: modelo de equipo no identificado\n\n\n',NULL,NULL,'soporte'),(6,'TMC-INC6',1,2,'2013-09-03 22:14:14',NULL,'2013-09-03 21:56:38',1,'Defensoría Penal Pública','Clauss Fridman R.','24238149','75390409','fcifuentes@touchmedia.cl','Amunategui 20, piso 2 CNT, Santiago – Chile',0,'CMA 4000','00000000000004','00000000000004','El cliente necesita subir el servidor CMA a su plataforma al dominio de la red, tambien se necesitan credenciales de administracion para la CMA.',NULL,NULL,'soporte'),(7,'TMC-INC7',1,2,'2013-09-03 22:14:29',NULL,'2013-09-03 21:48:13',1,'Defensoría Penal Pública','Clauss Fridman R.','24238149','75390409','chernandez@touchmedia.cl','Amunategui 20, piso 2 CNT, Santiago – Chile',0,'indefinido','00000','00000','INC000002832018\nFecha de creacion 30/10/2012\nFecha de atencion 06/11/2012\n\nFalla: Equipo Videoconferencia sucursal valdivia con problemas.\n\nObs: sin modelo de equipo ni serie',NULL,NULL,'soporte'),(8,'TMC-INC8',1,2,'2013-09-03 22:15:50',NULL,'2013-09-03 22:10:09',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','fcifuentes@touchmedia.cl','Bandera 76, piso 9, Santiago – Chile',0,'Touchcontrol','00000000000005','00000000000005','Conexión USB el touchcontrol se encuentra con problemas ya que no conecta ningun pendrive.',NULL,NULL,'soporte'),(9,'TMC-INC9',1,2,'2013-09-03 22:16:54',NULL,'2013-09-03 21:48:27',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','fcifuentes@touchmedia.cl','Bandera 76, piso 9, Santiago – Chile',0,'Pizarra Smart','00000000000009','00000000000009','Nos acaba de llegar un ticket por problemas con la pizarra del Hospital de Quillota. \n\nContacto:\nRoberto Castro 97488610\n',NULL,NULL,'soporte'),(10,'TMC-INC10',1,2,'2013-09-03 22:17:06',NULL,'2013-09-03 21:57:18',1,'Defensoría Penal Pública','Clauss Fridman R.','24238149','75390409','chernandez@touchmedia.cl','Amunategui 20, piso 2 CNT, Santiago – Chile',0,'CMA','00000','00000','INC000003752149\n\nFecha de creacion 10/07/2013\nFecha de atencion --\n\nFalla: Servidor CMA no está cargando interfaz gráfica de administración.\n\n',NULL,NULL,'soporte'),(11,'TMC-INC11',1,2,'2013-09-03 22:18:12',NULL,'2013-09-03 21:48:44',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','fcifuentes@touchmedia','Bandera 76, piso 9, Santiago – Chile',0,'Pizarra Smart','00000000000010','00000000000010','La pizarra presenta error en las camaras ubicadas en las esquinas.',NULL,NULL,'soporte'),(12,'TMC-INC12',1,2,'2013-09-03 22:18:21',NULL,'2013-09-03 21:57:37',1,'Defensoría Penal Pública','Clauss Fridman R.','24238149','75390409','chernandez@touchmedia.cl','Amunategui 20, piso 2 CNT, Santiago – Chile',0,'CMA','00000','00000','INC000003505650\nFecha de creacion 11/07/2013\nFecha de atencion 12/07/2013\n\nFalla: El cliente necesita subir el servidor CMA a su plataforma al dominio de la red, tambien se necesitan credenciales de administracion para la CMA.',NULL,NULL,'soporte'),(13,'TMC-INC13',1,2,'2013-09-03 22:20:13',NULL,'2013-09-03 21:48:58',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','fcifuentes@touchmedia.cl','Bandera 76, piso 9, Santiago – Chile',0,'HDX 7000','000000000000011','000000000000011','El equipo de videoconferencia presenta problemas de envio de contenido.',NULL,NULL,'soporte'),(14,'TMC-INC14',1,2,'2013-09-03 22:20:29',NULL,'2013-09-03 21:57:59',1,'Defensoría Penal Pública','Clauss Fridman R.','24238149','75390409','chernandez@touchmedia.cl','Amunategui 20, piso 2 CNT, Santiago – Chile',0,'cma','00000','00000','INC000003795365 \nFecha de creacion 23/07/2013\nFecha de atencion 24/07/2013\n\nFalla: Servidor CMA no está cargando interfaz gráfica de administración.',NULL,NULL,'soporte'),(15,'TMC-INC15',1,2,'2013-09-03 22:28:40',NULL,'2013-09-03 21:49:11',1,'Defensoría Penal Pública','Clauss Fridman R.','24238149','75390409','chernandez@touchmedia.cl','Amunategui 20, piso 2 CNT, Santiago – Chile',0,'HDX','00000','00000','INC000003832071\nFecha de creacion 02/08/2013\nFecha de atencion 02/08/2013\n\nFalla: \"Problema Reportado: Video conferencia no funciona\nPruebas Realizadas: \n- Problemas con diversos usuarios \n- Audio esta ok\n- Imagen se congela hoy y días anteriores también\n- Cliente descarta problema de fluido eléctri',NULL,NULL,'soporte'),(16,'TMC-INC16',1,2,'2013-09-03 22:33:30',NULL,'2013-09-03 22:08:21',1,'Defensoría Penal Pública','Clauss Fridman R.','24238149','75390409','chernandez@touchmedia.cl','Amunategui 20, piso 2 CNT, Santiago – Chile',0,'HDX','00000','00000','INC000003875207 \n\nFecha de creacion 14/08/2013\nFecha de atencion 16/08/2013\n\nFalla: Los equipos de videoconferencia estan presentando problemas de pixelacion y degradacion de imagen en las siguientes sedes: Valparaiso, Rancagua, Puerto Montt y Regional Sur.\n',NULL,NULL,'soporte'),(17,'TMC-INC17',1,2,'2013-09-03 22:44:35',NULL,'2013-09-03 22:08:53',1,'Defensoría Penal Pública','Clauss Fridman R.','24238149','75390409','chernandez@touchmedia.cl','Amunategui 20, piso 2 CNT, Santiago – Chile',0,'VSX','000000','00000','INC000003878053\n\nFecha de creacion 14/08/2013\nFecha de atencion 20/08/2013\n\nFalla: Se necesita un cable para microfono de VSX 7000, ya que el existente se encuentra malo',NULL,NULL,'soporte'),(18,'TMC-INC18',1,2,'2013-09-05 14:28:55','2013-09-05 20:30:49','2013-09-05 20:33:23',3,'Instituto Profesional DUOC','Alexis Peña Maldonado','23540085','98299984','apenam@duoc.cl','Eliodoro Yañez 1595 - Piso 11 - Providencia',0,'88130911BF3CCN','88130911BF3CCN','88130911BF3CCN','El equipo se reinicia reiteradas veces al estar conectado en una videoconferencia.','Alexis,\n                Me comunique con el cliente y me indica que el equipo no ha presentado problemas, si el equipo volviese a reiniciarse te comunicas conmigo. Se realizaron las siguientes tareas:\n•	Actualización del equipo a la última versión, sin problemas.\n•	Prueba de videoconferencia (1hra),',NULL,'soporte'),(19,'TMC-INC19',1,2,'2013-09-24 16:10:54',NULL,'2013-09-24 15:22:27',3,'Instituto Profesional DUOC','Alexis Peña Maldonado','23540085','98299984','apenam@duoc.cl','Eliodoro Yañez 1595 - Piso 11 - Providencia',0,'CR3120123004','CR3120123004','CR3120123004','El equipo presenta problemas con los horarios en el Equipo RMX y CMA de DUOC.',NULL,NULL,'soporte'),(20,'TMC-INC20',1,2,'2013-09-24 17:06:12',NULL,'2013-09-24 19:46:57',4,'Latin America Power','Juan Pablo Cousins S','28203249 ','956689685','juanpablo.cousins@latampower.com','Cerro El Plomo, 5.420 – Of. 705',0,'QDX 6000','Q60914BE1B7BF7E5','Q60914BE1B7BF7E5','El equipo presenta fallas de reinicio del sistema constantemente.',NULL,NULL,'soporte'),(21,'TMC-INC21',1,2,'2013-09-26 19:12:40',NULL,'2013-09-26 18:59:35',5,'Embotelladora Andina','Joe Luis Reyes','82391770','82391770','joe.reyes2@hp.com','Avenida Miraflores 9153',0,'HDX 7000','88131311C094CN','88131311C094CN','Falta licencia Multipunto',NULL,NULL,'soporte'),(22,'TMC-INC22',1,2,'2013-09-26 22:58:36',NULL,'2013-09-30 21:05:05',3,'Instituto Profesional DUOC','Alexis Peña Maldonado','23540085','98299984','mramirez@touchmedia.cl','Eliodoro Yañez 1595 - Piso 11 - Providencia',0,'HDX7000','lkojnhbgvfcdxscf','mjnhbgvfcdxcfvgb','TEST DE NUEVO FORMATO DE CORREO TICKET A CLIENTE',NULL,NULL,'soporte'),(23,'TMC-INC23',1,2,'2013-09-30 22:05:16',NULL,'2013-10-02 20:19:11',6,'CorpBanca','Cesar Perez','26878234','98265040','fcifuentes@touchmedia.cl','Huerfanos 1072',0,'HDX 7000','88124211B6D1CN','88124211B6D1CN','prueba',NULL,NULL,'soporte'),(24,'TMC-INC24',1,2,'2013-09-30 22:11:29',NULL,'2013-10-02 20:19:19',6,'CorpBanca','Cesar Perez','26878234','98265040','chernandez@touchmedia.cl','Huerfanos 1072',0,'hdx','000000','000000','asdasdasd',NULL,NULL,'soporte'),(25,'TMC-INC25',1,2,'2013-10-02 20:51:01',NULL,'2013-10-02 20:15:08',1,'Defensoría Penal Pública','Clauss Fridman R.','24238149','75390409','jrjara@entel.cl','Amunategui 20, piso 2 CNT, Santiago – Chile',0,'HDX 4000','88122610FABECH','88122610FABECH','El equipo de videoconferencia se encuentra des-configurado.',NULL,NULL,'soporte'),(26,'TMC-INC26',1,2,'2013-10-03 16:27:14',NULL,'2013-10-03 15:32:49',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','fcifuentes@touchmedia.cl','Bandera 76, piso 9, Santiago – Chile',0,'VSX 7000','82073501B837AL','82073501B837AL','El subwoofer presenta problemas',NULL,NULL,'soporte'),(27,'TMC-INC27',1,2,'2013-10-03 16:36:19',NULL,'2013-10-03 15:56:49',6,'CorpBanca','Cesar Perez','26878234','98265040','fcifuentes@touchmedia.cl','Huerfanos 1072',0,'HDX 7000','88124211B6D1CN','88124211B6D1CN','Se necesita revisión de terminal CorpBanca por Licencias.',NULL,NULL,'soporte'),(28,'TMC-INC28',1,2,'2013-10-03 17:32:39',NULL,'2013-10-03 16:33:57',7,'Servicio de evaluación ambiental','Eduardo Rozas','26164000','26164000','eduardo.rozas@sea.gov.cl','Miraflores Nº 222, Pisos 7, 19 y 20',0,'HDX 7000','881132111932CN','881132111932CN','El equipo no envía contenido.',NULL,NULL,'soporte'),(29,'TMC-INC29',1,2,'2013-10-08 16:00:10',NULL,'2013-10-08 15:58:11',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','flineros@entel.cl','Bandera 76, piso 9, Santiago – Chile',0,'HDX 7000','88130811BEA8CN','88130811BEA8CN','Equipo de HOSPITAL PROVINCIAL DE HUASCO con problemas en conectividad con Gatekeeper y no puede realizar llamados.',NULL,NULL,'soporte'),(30,'TMC-INC30',1,2,'2013-10-11 19:35:18','2013-10-11 18:44:07','2013-10-11 18:44:12',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','flineros@entel.cl','Bandera 76, piso 9, Santiago – Chile',0,'HDX 7000','88130811bea8cn','88130811bea8cn','Equipo hospital provincial de huasco no realiza llamados.\nAl momento de realizar el llamado equipo alerta problemas de red.','Se llama a cliente y se verifica fallas de red, se indica llamar directamente a mesa ayuda entel informando problemas de conectividad en red.',NULL,'soporte'),(31,'TMC-INC31',1,2,'2013-10-11 21:37:43','2013-10-11 20:58:49','2013-10-11 20:58:54',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','flineros@entel.cl','Bandera 76, piso 9, Santiago – Chile',0,'HDX 7000','88130911BF44CN','88130911BF44CN','Se informa que el equipo tiene problemas con el micrófono.','\n•	Se verifica el estado del cable, no se encuentran problemas.\n•	Se verifica la conexión, el cable se encontraba mal conectado por el lado del códec.\n•	Se realizan pruebas de diagnóstico para comprobar el funcionamiento del micrófono, no se presentan problemas.\n\nEl equipo vuelve a estar operativo.\n',NULL,'soporte'),(32,'TMC-INC32',1,2,'2013-10-14 17:05:59','2013-10-21 12:16:08','2013-10-21 12:16:33',5,'Embotelladora Andina','Joe Luis Reyes','82391770','82391770','joe.reyes2@hp.com','Avenida Miraflores 9153',0,'HDX 7000','88131311C094CN','88131311C094CN','Cliente con problemas en visualizacion de llamados multipunto, no ve todos los participantes de la videoconferencia.','Se contacta con Joe Reyes y se indica cambiar configuracion de visualizacion multipunto de equipo a modo discusion. Adicionalmente se recomienda realizar este cambio a todos los equipos.\nCliente realizara pruebas y nos contactara en caso de fallas.\n15/10 Se llama a cliente y aun no realiza pruebas.\n',NULL,'soporte'),(33,'TMC-INC33',1,2,'2013-10-17 13:32:01','2013-10-17 12:39:26','2013-10-17 12:39:32',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','flineros@entel.cl','Bandera 76, piso 9, Santiago – Chile',0,'MGC 100','89895','89895','Alerta major por tarjeta IP 3, la tarjeta no se registra al gatekeeper.','Se verifica el problema, y se reinicia la Tarjeta, el equipo vuelve a estar operativo.',NULL,'soporte'),(34,'TMC-INC34',1,2,'2013-10-21 13:24:28','2013-10-21 12:29:24','2013-10-21 12:29:29',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','fcifuentes@touchmedia.cl','Bandera 76, piso 9, Santiago – Chile',0,'HDX 7000','ASD123','ASD123','El equipo presenta problemas de Red.','Se verifican el cableado y las configuraciones del equipo de videoconferencia y no se encuentran problemas, se conversa con el administrador de la red para poder solucionar el problema con la red.\n\nSe realizan las pruebas de videoconferencia y el equipo vuelve a estar operativo.',NULL,'soporte'),(35,'TMC-INC35',1,2,'2013-10-21 13:44:52','2013-10-21 12:53:38','2013-10-21 12:53:46',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','fcifuentes@touchmedia.cl','Bandera 76, piso 9, Santiago – Chile',0,'Polycom 5300LF-ST10','asd145','asd145','Se presenta problemas con VPB de Minsal.','Estimado se confirma con cliente que problema con Video Border Proxy modelo ST es que no puede realizar llamados hacia afuera de su red, solo puede recibir llamados. Se analizó el inconveniente y se detectó que no está instalado según recomendación del fabricante, actualmente el equipo tiene configu',NULL,'soporte'),(36,'TMC-INC36',1,2,'2013-10-21 13:55:51','2013-10-21 13:06:49','2013-10-21 13:06:55',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','fcifuentes@touchmedia.cl','Bandera 76, piso 9, Santiago – Chile',0,'RMX 2000','VR2121230023','VR2121230023','El cliente presenta problemas con RMX Manager el cual no funciona la aplicación.','Se realizan pruebas de coneccion con RMX Manager. el programa no funciona ya que la direccion ip que tiene el computador se encuentra bloqueada por algún firewall, se cambia el direccionamiento por uno que tuviese los permisos correspondientes y el programa vuelve a estar operativo.',NULL,'soporte'),(37,'TMC-INC37',1,2,'2013-10-21 15:58:12','2013-10-28 13:19:28','2013-10-28 13:19:34',6,'CorpBanca','Cesar Perez','26878234','98265040','cesar.perez@corpbanca.cl','Huerfanos 1072',0,'HDX 7000','8208330A99D8CN','8208330A99D8CN','Se actualiza el equipo HDX de la 2.0 a 3.1','El equipo queda actualizado a la ultima versión 3.2.',NULL,'soporte'),(38,'TMC-INC38',1,2,'2013-10-21 17:18:17','2013-10-28 14:31:09','2013-10-28 14:31:13',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','fcifuentes@touchmedia.cl','Bandera 76, piso 9, Santiago – Chile',0,'Lenovo all in one','VS70014952','VS70014952','El equipo presenta falla en el sistema operativo.','Se revisa el equipo, efectivamente presenta problemas con el sistema operativo. El equipo queda en laboratorio.',NULL,'soporte'),(39,'TMC-INC39',1,2,'2013-10-28 14:33:50','2013-10-28 15:30:23','2013-10-28 15:30:28',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','fcifuentes@touchmedia.cl','Bandera 76, piso 9, Santiago – Chile',0,'RSS 4000','0004F29494EE','0004F29494EE','Mauricio Muñoz nos pide lo siguiente para el RSS\n\n-SIN IVR O ALGO MAS CORTO.\n-PROBLEMAS DE GRABACION RSS.\n-NO ESTA PROGRAMADA A LA HORA.\n','La instalación no está entregada completamente por el fabricante, por lo tanto la gente de Polycom está en estos momento realizando las configuraciones necesarias en los equipos de infraestructura.',NULL,'soporte'),(40,'TMC-INC40',1,2,'2013-10-28 14:34:39','2013-10-28 15:27:10','2013-10-28 15:27:15',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','fcifuentes@touchmedia.cl','Bandera 76, piso 9, Santiago – Chile',0,'RMX 2000','VR2121230023','VR2121230023','Favor revisar el inconveniente que tiene Mauricio con la RMX.\n\nProblemas con equipo central de video conferencia ubicado en rmx con spiker exclusivo funciona  con problema. Cuan lo activa y lo desactiva hay sitios que se quedan abiertos.\n\nNombre:             MAURICIO muñoz\nFono:    MAURICIO.MUNOZ@MI','se explica el funcionamiento de la operacion que quiere realizar.',NULL,'soporte'),(41,'TMC-INC41',1,2,'2013-10-28 14:39:04','2013-10-28 15:24:46','2013-10-28 15:24:50',6,'CorpBanca','Cesar Perez','26878234','98265040','fcifuentes@touchmedia.cl','Huerfanos 1072',0,'HDX 7000','8208290A947ECN ','8208290A947ECN ','Estan en video entre chile y colombia y se ha caido 2 veces la conexion. Favor revisar e informar si encuentran algo.','Se verifican las configuraciones de los equipos y no se encuentran problemas, se indica revisión con la conexión para verificar problemas de error. los equipos vuelven a estar operativos.',NULL,'soporte'),(42,'TMC-INC42',1,2,'2013-10-28 14:42:11','2013-10-28 15:19:54','2013-10-28 15:19:59',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','fcifuentes@touchmedia.cl','Bandera 76, piso 9, Santiago – Chile',0,'hdx 7000','88130811BEB0CN','88130811BEB0CN','Favor llamar a Mauricio Muñoz, informa problemas para realizar video conferencia con Concepción.','Se realizaron las siguientes pruebas.\nSe verifica la configuración de la RMX, no presenta problemas.\nSe realizaron pruebas de videoconferencia, se presentaron problemas por un lapso luego el equipo volvió a conectarse.\nSe realiza prueba con el equipo HDX para llamar hacia la RMX, no presenta \nLa pla',NULL,'soporte'),(43,'TMC-INC43',1,2,'2013-10-28 14:46:12','2013-10-28 15:18:14','2013-10-28 15:18:19',6,'CorpBanca','Cesar Perez','26878234','98265040','fcifuentes@touchmedia.cl','Huerfanos 1072',0,'HDX 7000','8208290A94BDCN','8208290A94BDCN','Estimado Cesar, buenas tardes, favor tu ayuda, necesito si me puedes enviar el nombre del proveedor que realizo la instalación de la video conferencia en huérfanos # 1072, piso 5, debido a que una caja en donde se conectan los cables VGA y hdmi, se rompió y hay que cambiarla, s dejo conectado todo, ','Se gestiona visita a terrento.',NULL,'soporte'),(44,'TMC-INC44',1,2,'2013-10-28 14:48:33','2013-10-28 15:15:15','2013-10-28 15:17:44',6,'CorpBanca','Cesar Perez','26878234','98265040','fcifuentes@touchmedia.cl','Huerfanos 1072',0,'HDX 7000','88130811BEADCN','88130811BEADCN','Favor su ayuda con el siguiente incidente.\nusuario: cesar villagra\nestablecimiento: hospital de puerto montt\ndirección: seminario s/n\nciudad: puerto montt\ntelefono:99419083\ncorreo: cvillagra@ssdr.gov.cl\n\ncomentarios: Usuario indica que después de migración VC no responde.\n\nip de puerta de enlace: 10','Me comunique con el cliente y se realizaron las siguientes tareas.\n\n•	Se verifica el cableado del equipo, no presenta problemas.\n•	Se verifica la configuración del sistema, no presenta problemas.\n•	Se realiza una prueba de videoconferencia, no se logra la conexión.\n',NULL,'soporte'),(45,'TMC-INC45',1,2,'2013-10-28 14:50:57','2013-10-28 15:17:32','2013-10-28 15:17:37',6,'CorpBanca','Cesar Perez','26878234','98265040','fcifuentes@touchmedia.cl','Huerfanos 1072',0,'HDX 7000','8208290A94BDCN','8208290A94BDCN','Estimados, favor coordinar para las 14:00 hrs soporte técnico, para realizar pruebas de envío de contenido en la Sala de Presidencia de CorpBanca (RN660 P18), puesto que hoy no se pudo realizar este procedimiento.','Segun cliente el cable VGA se encuentra en mal estado, ya que la entrada que se encuentra en la pared esta suelta. Se agenda visita in-situ.',NULL,'soporte'),(46,'TMC-INC46',1,2,'2013-10-28 15:09:03','2013-10-28 15:15:47','2013-10-28 15:15:52',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','fcifuentes@touchmedia.cl','Bandera 76, piso 9, Santiago – Chile',0,'HDX 7000','88130911BF42CN','88130911BF42CN','Cliente informa tener problemas con el Mute del HDX.\n\nSeremi Antofagasta\nEduardo Alvarez\nFC:55-2655058\n','                Me comunique con el cliente, y solo quería aclarar una duda con el mute de los equipo, el intentaba dar mute/desmute pero no lograba efecto alguno, el problema pasaba ya que el administrador de la multipunto le daba mute remotamente a los equipos.\nAtento a sus comentarios.\n',NULL,'soporte'),(47,'TMC-INC47',1,2,'2013-10-30 17:31:38','2013-10-30 17:37:10','2013-10-30 17:37:15',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','flineros@entel.cl','Bandera 76, piso 9, Santiago – Chile',0,'TOUCH CONTROL POLYCOM','8A1211203F01CU','8A1211203F01CU','Equipo Touch Control en el OAS Castro no tiene conectividad con HDX de sala.','Equipo con puerta de enlace mal configurada, se corrige dato de puerta de enlace logrando conectividad con HDX.',NULL,'soporte'),(48,'TMC-INC48',1,2,'2013-10-30 21:36:15',NULL,'2013-10-30 21:37:48',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','flineros@entel.cl','Bandera 76, piso 9, Santiago – Chile',0,'VSX 7000','00000','00000','Equipo vsx de Hospital Alto Hospicio no muestra IP.',NULL,NULL,'soporte'),(49,'TMC-INC49',1,2,'2013-10-30 21:37:53','2013-10-30 21:41:09','2013-11-12 15:27:19',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','flineros@entel.cl','Bandera 76, piso 9, Santiago – Chile',0,'HDX 7000','88131211C048CN','88131211C048CN','Equipo de SS Aconcagua con problemas de camara y touch control desactualizado.','Equipo ademas con falla en control remoto se solicitara visita a terreno.',NULL,'soporte'),(50,'TMC-INC50',1,2,'2013-11-12 15:24:46','2013-11-12 15:27:03','2013-11-12 15:27:11',1,'Defensoría Penal Pública','Clauss Fridman R.','24238149','75390409','cfridman@entel.cl','Amunategui 20, piso 2 CNT, Santiago – Chile',0,'HDX 7000','8211470DA60BCH','8211470DA60BCH','Servicio de videoconferencia no funciona.','el problema se presenta con la RMX, se enviara otro ticket para formular el problema.',NULL,'soporte'),(51,'TMC-INC51',1,2,'2013-11-12 15:27:26','2013-11-12 18:27:50','2013-11-12 18:27:56',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','flineros@entel.cl','Bandera 76, piso 9, Santiago – Chile',0,'HDX 6000','8811361147C9CP','8811361147C9CP','Se realizaran pruebas con InterSystems para verificar funcionamiento del VBP','Se realiza prueba de videoconferencia satisfactoriamente.',NULL,'soporte'),(52,'TMC-INC52',1,2,'2013-11-12 18:28:04',NULL,'2013-11-12 21:04:33',6,'CorpBanca','Cesar Perez','26878234','98265040','cesar.perez@corpbanca.cl','Huerfanos 1072',0,'VBP 5300 ST','1234B03308','1234B03308','Según lo conversado solo se hará cambio de la Password: CorPbanca2013, mientras realizas la gestión para poder ingresar vía LAN a la administración del VBP.',NULL,NULL,'soporte'),(53,'TMC-INC53',1,2,'2013-11-18 14:10:19','2013-11-18 14:46:16','2013-11-18 14:46:21',1,'Defensoría Penal Pública','Clauss Fridman R.','24238149','75390409','cfridman@entel.cl','Amunategui 20, piso 2 CNT, Santiago – Chile',0,'HDX 7000','8211470DA60BCH','8211470DA60BCH','Se presenta problema con RMX , se levantara otro ticket constatando el problema el cual esta presentando, el cliente no puede entrar con su datos al RMX manager.','El cliente creara un ticket para verificar problema con inicio de sesión de RMX Manager.',NULL,'soporte'),(54,'TMC-INC54',1,2,'2013-11-18 14:16:29','2013-11-18 14:45:31','2013-11-18 14:45:35',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','fcifuentes@touchmedia.cl','Bandera 76, piso 9, Santiago – Chile',0,'VBP 5300 ST','VP11B78C','VP11B78C','Se realizan pruebas con empresa Intersystem, el cual pidió MINSAL para verificar configuraciones de equipo VBP 5300 ST de MINSAL, el cual concuerdan con la configuraciones de nuestro VBP. las pruebas fueron satisfactorias.','La prueba se realiza satisfactoriamente.',NULL,'soporte'),(55,'TMC-INC55',1,2,'2013-11-18 14:36:08','2013-11-18 14:45:00','2013-11-18 14:45:05',6,'CorpBanca','Cesar Perez','26878234','98265040','fcifuentes@touchmedia.cl','Huerfanos 1072',0,'VBP 4555 E','abcdfg','abcdfg','El cliente pide desactivar la vista de administración WEB por el lado publico. se conversa con cliente y solo se realiza cambio de contraseña a \"Corp2013\" ya que no hay administración local.','Se realiza el cambio de contraseña por \"Corp2013\".',NULL,'soporte'),(56,'TMC-INC56',1,2,'2013-11-21 20:15:38','2013-11-22 17:29:54','2013-11-22 17:29:58',1,'Defensoría Penal Pública','Clauss Fridman R.','24238149','75390409','cfridman@entel.cl','Amunategui 20, piso 2 CNT, Santiago – Chile',0,'HDX ','00000','00000','Equipo presenta problemas de audio.','Se agenda visita de tecnico a terreno para el dia 22/11 a las 9.00\n\nLuego de visita tecnica se validan configuraciones y conexiones y equipo funciona sin problemas.',NULL,'soporte'),(57,'TMC-INC57',1,2,'2013-12-09 13:56:32','2013-12-09 15:06:00','2013-12-09 15:06:12',17,'Entel Call Center S.A.','Francisco Lineros','123123','123123','fcifuentes@touchmedia.clk','Avenida Vicuña Mackenna 3747',0,'VSX 7000','xxzxzxzxzxzx','xxzxzxzxzxzx','El dispositivo VSX 7000 presenta problemas con conector de red, se gestiona visita a terreno.','Se realiza visita a terreno el equipo se encuentra con mantencion por lo tanto se enviara a nuestro establecimiento su revision.',NULL,'soporte'),(58,'TMC-INC58',1,2,'2013-12-09 14:11:40','2013-12-09 15:07:02','2013-12-09 15:07:06',6,'CorpBanca','Cesar Perez','26878234','98265040','fcifuentes@touchmedia.cl','Huerfanos 1072',0,'VBP/ST','HU7VJC','HU7VJC','Se configura Access Proxy.','El Dispositivo VBP/ST se encuentra configurado, el cliente revisara los puertos ya que estos no se encuentra habilitados.',NULL,'soporte'),(59,'TMC-INC59',1,2,'2013-12-09 14:15:03','2013-12-09 15:08:58','2013-12-09 15:09:03',47,'Casino de Juegos Temuco S.A.-DREAMS','No Existe','123123','123123','noexiste@casino.com','Avenida Alemania 945',79,'HDX8000','8211030D3D3FCG','8211030D3D3FCG','Favor contactar a cliente DREAMS y entregar soporte, según lo siguiente:\n1.	Habilitar 3 Meeting Room con capacidad max de 4 participantes en RMX.\n2.	Habilitar directorio para todas las salas a nivel nacional Dreams (Solo en HDX)\n3.	Habilitar en el Directorio los 3 MR.\n','Se entrega el soporte conrrespodientes y se realiza una capacitacion al respecto.',NULL,'soporte'),(60,'TMC-INC60',1,2,'2013-12-09 14:20:27','2013-12-09 15:10:17','2013-12-09 15:10:22',3,'Instituto Profesional DUOC UC','Alexis Peña Maldonado','23540085','98299984','apenam@duoc.cl','Eliodoro Yañez 1595 Piso 11',34,'HDX7000','88124311B7A0CN','88124311B7A0CN','Problemas con equipos de videoconferencia, estos al configurar el segundo monitor, liego al apagarse este se des configura solo.','Se realiza soporte al cliente, el cliente realizaba mal las configuraciones ademas se revisan los equipos y no se encuentran problema alguno.',NULL,'soporte'),(61,'TMC-INC61',1,2,'2013-12-09 14:22:34','2013-12-09 15:10:44','2013-12-09 15:10:48',6,'CorpBanca','Cesar Perez','26878234','98265040','fcifuentes@touchmedia.cl','Huerfanos 1072',0,'HDX 7000','88124211B6D1CN','88124211B6D1CN','Agendamiento de videoconferencia con NY, Merced 480 y Huerfanos ','Se realizo Videoconferencia exitosamente.',NULL,'soporte'),(62,'TMC-INC62',1,2,'2013-12-09 14:30:54','2013-12-09 15:11:26','2013-12-09 15:11:36',36,'Entel S.A.','Jorge Katted','123123','123123','noexiste@entel.com','Avenida Andrés Bello 2687 Piso 14',0,'VBP/ST','JK5RKT','JK5RKT','Activar SNMP en VBP’s y PRMM’s.Comunidad: minsallwan\n','Se activan los SNMP en los equipo requeridos por Entel.',NULL,'soporte'),(63,'TMC-INC63',1,2,'2013-12-09 14:33:01','2013-12-09 15:30:53','2013-12-09 15:30:58',6,'CorpBanca','Cesar Perez','26878234','98265040','fcifuentes@touchmedia.cl','Huerfanos 1072',0,'RMX 1500','CR3121019006','CR3121019006','Agendamiento videoconferencia con Corpbanca Chile, Cleary Buenos Aires y Cleary NY','La Videoconferencia se realiza exitosamente.',NULL,'soporte'),(64,'TMC-INC64',1,2,'2013-12-09 14:37:09','2013-12-09 15:31:45','2013-12-09 15:31:49',6,'CorpBanca','Cesar Perez','26878234','98265040','cesar.perez@corpbanca.cl','Huerfanos 1072',0,'HDX 7000','88124211B6D1CN','88124211B6D1CN','Se presenta problema con conector VGA utilizado proyetor este se encuentra en mal estado, se realiza gestion visita a terreno.','Se envia personal a in-situ el cual soluciono el problema con conector VGA.',NULL,'soporte'),(65,'TMC-INC65',1,2,'2013-12-09 14:39:38','2013-12-09 15:32:58','2013-12-09 15:33:06',6,'CorpBanca','Cesar Perez','26878234','98265040','fcifuentes@touchmedia.cl','Huerfanos 1072',0,'HDX 7000','88124211B6D1CN  ','88124211B6D1CN  ','Pruebas con dispositivos de videoconferencia ya que se aplicaron QoS en los dispositivos.','Se realizan los cambios por parte del cliente, luego se realizan las pruebas y salen exitosamente.',NULL,'soporte'),(66,'TMC-INC66',1,2,'2013-12-09 14:41:31','2013-12-09 15:33:53','2013-12-09 15:34:00',36,'Entel S.A.','Jorge Katted','123123','123123','noexiste@entel.com','Avenida Andrés Bello 2687 Piso 14',0,'VSX 7000','88124411976FCG','88124411976FCG','Se presenta prblemas con equipo VSX 7000 ubicado en servicio de salud Aconcagua.','El equipo no presenta problemas, el problema se encuentra en el punto de red el cual no se encuentra en el segmento de videconferencia.',NULL,'soporte'),(67,'TMC-INC67',1,2,'2013-12-09 14:43:16','2013-12-09 15:35:05','2013-12-09 15:35:10',36,'Entel S.A.','Jorge Katted','123123','123123','noexiste@entel.com','Avenida Andrés Bello 2687 Piso 14',0,'RMX 2000','VR2121230023','VR2121230023','Usuario no puede establecer la video conferencia, indica que le arroja un error con la RMX, al conectar el sitio aparece en negro.','Se realizan las pruebas necesarias con la RMX, se encuentran problemas con elevada perdida de paquetes, se envía el estado de la llamada a Entel para que verifiquen el caso con personal de redes.',NULL,'soporte'),(68,'TMC-INC68',1,2,'2013-12-09 14:51:54','2013-12-09 15:36:19','2013-12-09 15:36:23',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','fcifuentes@touchmedia.cl','Bandera 76, piso 9, Santiago – Chile',27,'HDX7000','881147116B73CN','881147116B73CN','Se presenta problemas con carro telemedicina de curanilahue.','El cliente tiene problemas al conectar el CMA-D, el cual no responde ya que no se encuentra conectado a un segmento de videoconferencia.',NULL,'soporte'),(69,'TMC-INC69',1,2,'2013-12-09 14:57:06','2013-12-09 15:37:08','2013-12-09 15:37:12',3,'Instituto Profesional DUOC UC','Alexis Peña Maldonado','23540085','98299984','fcifuentes@touchmedia.cl','Eliodoro Yañez 1595 Piso 11',34,'HDX7000','88124311B7A0CN','88124311B7A0CN','Integracion Lync con equipo polycom, el cliente necesita informacion.','Se envía las información necesaria al cliente en donde se encuentra con detalle el procedimiento que debe seguir para esta integración.',NULL,'soporte'),(70,'TMC-INC70',1,2,'2013-12-10 14:57:08',NULL,'2013-12-10 21:15:03',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','flineros@entel.cl','Bandera 76, piso 9, Santiago – Chile',27,'HDX7000','881147116B73CN','881147116B73CN','El Cliente mauricio Muñoz presenta problemas con MGC para realizar grabaciones.',NULL,NULL,'soporte'),(71,'TMC-INC71',1,2,'2013-12-16 16:38:17','2013-12-16 18:01:54','2013-12-16 18:02:00',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','fcifuentes@touchmedia.cl','Bandera 76, piso 9, Santiago – Chile',0,'RSS 4000','0004F29494EA','0004F29494EA','Se contacta a Mauricio Muñoz, indica que necesita realizar grabación con RSS a través del MGC, pero que al tratar de conectar el RSS pregunta por una ruta para grabar.\nSe deriva con proveedor para que configure el RSS para poder realizar llamadas con MGC.\nLa VC se realiza mañana a las 11 hrs. favor ','                Me comunique con Mauricio, el necesitaba información de cómo realizar unas grabaciones por MGC a través de un RSS él ya sabía cómo realizarlas solo tenía dudas sobre algunas configuraciones, de forma automática y de manera manual, se le entrego la ayuda correspondiente a Mauricio, se',NULL,'soporte'),(72,'TMC-INC72',1,2,'2013-12-16 16:42:50','2013-12-16 18:03:56','2013-12-16 18:04:04',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','flineros@entel.cl','Bandera 76, piso 9, Santiago – Chile',333,'VSX7000','8208430AD59EMK','8208430AD59EMK','Favor cambiar micrófono de VSX 7000 en SEREMI de Los Angeles, equipo venía desde SEREMI de Concepción.\nContacté a cliente, indica que desde hace unos días comenzó a fallar, y desde ayer que ya no funciona, no enciende luz ni envía audio. El cable y sus conectores se ven en buen estado, el micrófono ','Se envía técnico a in-situ para cambio de micrófono.',NULL,'soporte'),(73,'TMC-INC73',1,2,'2013-12-16 16:44:48','2013-12-16 18:06:46','2013-12-16 18:41:55',21,'Geopark Fell SpA','Francisco Fernández','123123','123123','fcifuentes@touchmedia.cl','Maipú 979',0,'HDX 4500','8213130E89C4CZ','8213130E89C4CZ','El cliente tiene problemas con la videoconferencia ya que esta se desconecta.','El problema es producto de la estabilidad de la red, al momento de realizar la llamada y revisar el estado de la llamada actual, esta muestra una alta cantidad de paquetes perdidos, es por eso, en el momento que estas en videoconferencia esta se pixel a tal grado que la conferencia se desconecta.',NULL,'soporte'),(74,'TMC-INC74',1,2,'2013-12-16 16:47:32','2013-12-16 18:43:06','2013-12-16 18:43:10',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','fcifuentes@touchmedia.cl','Bandera 76, piso 9, Santiago – Chile',0,'DMA 7000','JY9DZV1','JY9DZV1','Cliente reporta problema de conflicto de IP en equipo de Video Conferencia. Indica que al conectarse toma la IP del DMA. Al pasar esto se genera un conflicto de IP. La IP de equipo de VC es 10.120.1.13. Cliente necesita una solución urgente ya que se esta generando una operación de un paciente en vi','                Se realizaron las pruebas correspondientes, los equipos en ningún momento presentaban problemas es normal que al realizar la llamada al room este tome la dirección del servidor DMA, ya que es este el que realiza el trabajo de gatekeeper (10.120.1.13.',NULL,'soporte'),(75,'TMC-INC75',1,2,'2013-12-16 16:50:07','2013-12-16 18:45:25','2013-12-16 18:45:29',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','fcifuentes@touchmedia.cl','Bandera 76, piso 9, Santiago – Chile',27,'HDX7000','881147116B73CN','881147116B73CN','cliente presenta problemas con carro de telemedicina, este no realiza conexión con CMA-D.','El cliente no tenia conectividad, ya que no tenia cable de red conectado al carro. se explica al cliente como debe realizar la conexion.',NULL,'soporte'),(76,'TMC-INC76',1,2,'2013-12-16 16:54:57','2013-12-16 18:48:25','2013-12-16 18:48:30',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','fcifuentes@touchmedia.cl','Bandera 76, piso 9, Santiago – Chile',353,'VSX7000','82074609657FAK','82074609657FAK','Falla de equipo de VC con ip:10.18.10.226 presenta problemas de imagen (pantalla azul) \ndel códec con problema.\n','La cámara no se encontraba conectada al equipo de videoconferencia.',NULL,'soporte'),(77,'TMC-INC77',1,2,'2013-12-16 16:56:25','2013-12-16 18:49:21','2013-12-16 18:49:37',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','fcifuentes@touchmedia.cl','Bandera 76, piso 9, Santiago – Chile',353,'VSX7000','82074609657FAK','82074609657FAK','Falla de equipo de VC con ip:10.18.17.130 presenta problemas de imagen (pantalla azul) \ndel codec con problema.\n','La cámara no se encontraba conectado al equipo de videoconferencia.',NULL,'soporte'),(78,'TMC-INC78',1,2,'2013-12-16 16:57:06','2013-12-16 18:52:53','2013-12-16 18:52:58',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','fcifuentes@touchmedia.cl','Bandera 76, piso 9, Santiago – Chile',0,'PC-Cliente','xxxxx','xxxxx','El cliente en este caso Mauricio Muñoz no puede conectar un sitio externo a través del VBP-ST.','El soporte se realizó, el problema es producto de la conexión a través del VBP/ST, de acuerdo a tareas realizadas. \nSe verificaron las configuraciones, no se presentan problemas.\nSe realizan llamadas a través de VBP/ST, presenta problemas de conexión esta no se completa 100%.\n',NULL,'soporte'),(79,'TMC-INC79',1,2,'2013-12-16 17:00:13','2013-12-16 18:54:41','2013-12-16 18:54:46',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','fcifuentes@touchmedia.cl','Bandera 76, piso 9, Santiago – Chile',0,'RMX 2000','VR2121230023','VR2121230023','Problemas de VC en el hopispital de talca y arica no tengo imagen al transmitir via RMX.\nIP de Origen 10.120.1.25\nIP Hospital de talca  10.18.10.162\nIP Hospital de Arica 10.18.10.2\nCuando se realiza  la punto a punto funciona pero atraves de la rmx no funciona.','Se realizaron las pruebas correspondientes, con los sitios señalados por Mauricio, efectivamente existe un problema de red ya que al conectar estos dos sitios los cuales están en el mismo segmento ip, siempre hay uno que conecta y no muestra imagen',NULL,'soporte'),(80,'TMC-INC80',1,2,'2013-12-16 17:54:27','2013-12-16 18:55:45','2013-12-16 18:55:49',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','fcifuentes@touchmedia.cl','Bandera 76, piso 9, Santiago – Chile',0,'HDX 7000','88130911BF4BCN','88130911BF4BCN','La señal de Video Conferencia del ss arauco la imagen se ve en Negro.\n\nVC de destino  10.18.3.195\n','El equipo no presenta problemas, probablemente fue un problema del momento el cual afecto momentáneamente. Si se vuelve a presentar el mismo problema, Mauricio nos avisara para ver el problema en el momento.',NULL,'soporte'),(81,'TMC-INC81',1,2,'2013-12-17 17:22:14',NULL,'2013-12-17 17:25:47',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','flineros@entel.cl','Bandera 76, piso 9, Santiago – Chile',0,'HDX 7000','88130911BF37CN','88130911BF37CN','Equipo no enlaza al servidor CMA.',NULL,NULL,'soporte'),(82,'TMC-INC82',1,2,'2013-12-23 15:14:02','2013-12-23 13:42:47','2013-12-23 13:42:57',6,'CorpBanca','Cesar Perez','26878234','98265040','cesar.perez@corpbanca.cl','Huerfanos 1072',0,'HDX 7000','88124211B6D1CN','88124211B6D1CN','Agendamiento Videoconferencia entre EY Colombia y CorpBanca Chile.','La conferencia se realizo el dia miércoles 18 Dic a las 13.00 de Chile.',NULL,'soporte'),(83,'TMC-INC83',1,2,'2013-12-23 15:23:36','2013-12-23 13:45:52','2013-12-23 13:45:57',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','fcifuentes@touchmedia.cl','Bandera 76, piso 9, Santiago – Chile',0,'CMA-D','xxxxx','xxxxx','Se debe revisar configuracion del equipo, desde el CMA llega a la puerta de enlace (10.18.1.33) pero no al equipo (10.18.1.34).\nNombre:Juan Calor Flores\nFono:\nCelular:82946691\nEstablecimiento:Servicio de Salud Iquique\n','Estimados nos comunicamos con el cliente , verificamos las configuraciones del códec y realizamos las pruebas correspondientes, el equipo no logra conectividad desde el punto de red habilitado para la videoconferencia, se trata de conectar un notebook replicando los datos de direccionamiento.',NULL,'soporte'),(84,'TMC-INC84',1,2,'2013-12-23 15:26:03','2013-12-23 13:47:17','2013-12-23 13:47:38',6,'CorpBanca','Cesar Perez','26878234','98265040','cesar.perez@corpbanca.cl','Huerfanos 1072',0,'HDX 7000','8208290A947ECN','8208290A947ECN','realizar una video conferencia programada para el miércoles 18 de diciembre  a las 12:00 hrs (Chile) con HelmBank (sala 4 piso 3).','Se realiza conferencia el dia Miercoles 18 de Diciembre a las 12:00 hrs de Chile.',NULL,'soporte'),(85,'TMC-INC85',1,2,'2013-12-23 15:29:26','2013-12-23 14:05:05','2013-12-23 14:06:11',6,'CorpBanca','Cesar Perez','26878234','98265040','fcifuentes@touchmedia.cl','Huerfanos 1072',0,'HDX 7000','8211200D4E60PG','8211200D4E60PG','Agendar video conferencia entre Corpbanca Nueva York , Corpbanca Colombia (Policom Movible IP 180.168.86.121) y Rosario Norte (piso 18 sala 2). Esto está programado para el Jueves 19 de diciembre a las 14:30 hrs (Hora Chile).','Se realizo el día Miércoles 18 de diciembre  a las 12:00 hrs (Chile)  con HelmBank   (sala 4 piso 3). ',NULL,'soporte'),(86,'TMC-INC86',1,2,'2013-12-23 15:32:30','2013-12-23 14:24:14','2013-12-23 14:24:18',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','fcifuentes@touchmedia.cl','Bandera 76, piso 9, Santiago – Chile',337,'VSX7000','82073508FEF8AK','82073508FEF8AK','Antecedentes: Claudio Carrasco solicita visita en terreno, ya que codec de video conferencia no funciona, como no tenemos datos concretos se solicita personal en terreno.','                Me comunique con el cliente, el equipo se encuentra en perfecto estado, el problema que se presenta es de red, no tenemos conectividad en la red de videoconferencia. Realizamos pruebas de conectividad a través de un pc, ingresamos los mismo datos de direccionamiento a este.',NULL,'soporte'),(87,'TMC-INC87',1,2,'2013-12-23 15:33:44','2013-12-24 11:42:40','2013-12-24 11:42:44',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','fcifuentes@touchmedia.cl','Bandera 76, piso 9, Santiago – Chile',0,'VBP-E','54396801377B','54396801377B','Diagnóstico: No emite ni recibe llamadas ip\nAntecedentes: ip pública 186.67.71.22\nFavor revisar que este todo bien en las configuraciones del VBP-E\n','Se revisaron las configuraciones del equipo el cual no presenta problemas, se realizaron pruebas punto a punto y multipunto el cual no presenta problemas, estaremos pendiente si vuelve a suceder. ',NULL,'soporte'),(88,'TMC-INC88',1,2,'2013-12-23 15:36:51','2013-12-24 11:43:37','2013-12-24 11:43:41',43,'FAO Reg. Off for Latin America and the Caribb','No Existe','123123','123123','noexiste@fao.com','Avenida Dag Hammarskjöld 3241',0,'RPD','xxxxx','xxxxx','Te escribo por un tema que tengo pendiente:\n1.	El año pasado compramos una licencia de Real Presence a TOUCHMEDIA\n2.	Tengo el certificado de la licencia y la clave para poder ingresar\n3.	Necesito que me des el link exacto para descargar el software \n4.	Poer ser  a un sitio POLYCOM para . descargar e','Se le entrego el apoyo necesario para descargar e ingresar la licencia al software.',NULL,'soporte'),(89,'TMC-INC89',1,2,'2013-12-26 17:42:14',NULL,'2013-12-27 15:36:44',6,'CorpBanca','Cesar Perez','26878234','98265040','cesar.perez@corpbanca.cl','Huerfanos 1072',0,'RMX 2000','CR3121019006','CR3121019006','Se agenda Videoconferencia a las 12:30 horas con los siguientes terminales Huerfanos 1072, Corpbanca NY y RN piso 24.',NULL,NULL,'soporte'),(90,'TMC-INC90',1,2,'2013-12-26 17:43:24','2014-01-07 13:27:29','2014-01-07 13:27:35',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','flineros@entel.cl','Bandera 76, piso 9, Santiago – Chile',0,'RPMM','3272714779252609','3272714779252609','El equipo no realiza Streaming via internet.','El soporte queda a cargo de Polycom para la revision y configuraciones de RPMM, ya que este no puede realizar el streaming fuera de la Red de Minsal.',NULL,'soporte'),(91,'TMC-INC91',1,2,'2013-12-26 17:48:52','2013-12-27 15:34:09','2013-12-27 15:34:14',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','flineros@entel.cl','Bandera 76, piso 9, Santiago – Chile',27,'HDX7000','881147116B73CN','881147116B73CN','Antecedentes: Usuario reporta problemas con videoconferencia, no logra completar servicio de videoconferencia con otro establecimiento, figura realizando llamada pero no logra la conexion, ip del equipo es la correcta (10.18.16.226 y 10.18.16.227 para touch control), se descartaron puntos de red, so','Se valida con cliente que problema de comunicacion corresponde a red. Se escala a entel.',NULL,'soporte'),(92,'TMC-INC92',1,2,'2013-12-27 17:26:03',NULL,'2014-01-07 13:26:04',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','flineros@entel.cl','Bandera 76, piso 9, Santiago – Chile',0,'RMX 2000','VR2121230023','VR2121230023','Se genera incidencia para revisión preventiva del equipo, equipo presento reinicio automatico.',NULL,NULL,'soporte'),(93,'TMC-INC93',1,2,'2014-01-07 13:07:24','2014-01-07 13:25:12','2014-01-07 13:25:17',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','fcifuentes@touchmedia.cl','Bandera 76, piso 9, Santiago – Chile',0,'HDX 7000','xxxxxxxxx','xxxxxxxxx','Conexión con Access point.\n','                El cliente necesitaba conectar el router al AP de los carros de telemedicina, se le entrego la ayuda necesaria para realizar esta acción, estamos en espera de las pruebas que efectuara.\n',NULL,'soporte'),(94,'TMC-INC94',1,2,'2014-01-07 14:27:43','2014-01-07 13:29:03','2014-01-07 13:29:07',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','fcifuentes@touchmedia.cl','Bandera 76, piso 9, Santiago – Chile',320,'HDX7000','88130911BF41CN','88130911BF41CN','Antecedentes: Usuario reporta problemas con videoconferencia, no logra completar servicio de videoconferencia con otro establecimiento, figura realizando llamada pero no logra la conexion, ip del equipo es la correcta (10.18.16.226 y 10.18.16.227 para touch control), se descartaron puntos de red, so','Se realizaron las pruebas de diagnósticos correspondientes, al realizar un ping este no encuentra destino. El equipo se encuentra en buenas condiciones, el problema es netamente de red, favor de verificar la conectividad hacia el códec de videoconferencia.\n',NULL,'soporte'),(95,'TMC-INC95',1,2,'2014-01-07 14:29:19','2014-01-07 13:30:41','2014-01-07 13:30:47',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','fcifuentes@touchmedia.cl','Bandera 76, piso 9, Santiago – Chile',0,'RSS 4000','0004F29494EA','0004F29494EA','El cliente Mauricio Muñoz necesita credenciales para los RSS.\n','Se crean las credenciales correspondientes.\n',NULL,'soporte'),(96,'TMC-INC96',1,2,'2014-01-07 14:30:35','2014-01-07 13:31:47','2014-01-07 13:31:56',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','fcifuentes@touchmedia.cl','Bandera 76, piso 9, Santiago – Chile',0,'RMX 2000','VR2121230023','VR2121230023','\"Necesito ayuda URGENTE con estos sitios.\nLos Sitios no tienen imagen y/o están sin audio.\n\"\n','Se realizaron las pruebas correspondientes. El gatekeeper se encontraba deshabilitado, cuando habilitaba la opción y al momento de realizar una llamada, el equipo funciona correctamente pero al deshabilitar esta opción, el equipo no recibe imagen ni audio. El problema puede tratarse de rutas, cuando',NULL,'soporte'),(97,'TMC-INC97',1,2,'2014-01-07 14:31:37','2014-01-07 13:32:59','2014-01-07 13:33:04',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','flineros@entel.cl','Bandera 76, piso 9, Santiago – Chile',0,'HDX 7000','xxxxxxx','xxxxxxx','Conexión con Access point.\n','El cliente logra la conexión con Access point. Pta. Arenas\n',NULL,'soporte'),(98,'TMC-INC98',1,2,'2014-01-07 14:32:34','2014-01-07 13:33:56','2014-01-07 13:34:00',1,'Defensoría Penal Pública','Clauss Fridman R.','24238149','75390409','cfridman@entel.cl','Amunategui 20, piso 2 CNT, Santiago – Chile',0,'Derco','xxxxxxx','xxxxxxx','Ricardo, una ayuda, necesito llamar a un centro de convenciones en Kansas (USA), la IP es la 67.53.93.206, me puedes indicar los pasos a seguir considerando que tenemos el VBP en la red, muchas gracias.\n','Se presta la ayuda necesaria para realizar la llamada.\n',NULL,'soporte'),(99,'TMC-INC99',1,2,'2014-01-07 14:33:47','2014-01-07 13:35:13','2014-01-07 13:35:20',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','flineros@entel.cl','Bandera 76, piso 9, Santiago – Chile',0,'HDX 7000','xxxxxxx','xxxxxxx','Conexión con Access point Hosiptal Antofagasta.','Se entrega la ayuda necesaria para la conectividad con AP.',NULL,'soporte'),(100,'TMC-INC100',1,2,'2014-01-07 14:34:40','2014-01-07 13:36:13','2014-01-07 13:36:17',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','fcifuentes@touchmedia.cl','Bandera 76, piso 9, Santiago – Chile',0,'HDX 7000','xxxxxxx','xxxxxxx','Conexión con Access point Hospital Arica.\n','Se entrega la ayuda necesaria para la conectividad con AP.\n',NULL,'soporte'),(101,'TMC-INC101',1,2,'2014-01-07 14:36:08','2014-01-07 13:37:20','2014-01-07 13:37:25',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','fcifuentes@touchmedia.cl','Bandera 76, piso 9, Santiago – Chile',0,'RMX 2000','VR2121230023','VR2121230023','Se genera incidencia para revisión preventiva del equipo, para identificar causa de fallo de 40 minutos, que el equipo se encontraba sin conexión.\n','Se realiza Upgrade de software al equipo según recomendaion de polycom, el equipo se encuentra operativo.\n',NULL,'soporte'),(102,'TMC-INC102',1,2,'2014-01-07 14:37:13','2014-01-07 13:38:21','2014-01-07 13:38:25',6,'CorpBanca','Cesar Perez','26878234','98265040','fcifuentes@touchmedia.cl','Huerfanos 1072',0,'HDX 7000','xxxxxxx','xxxxxxx','\"De acuerdo a lo solicitado para realizar VideoConferencia entre CorpBanca Chile y su empresa le detallo la información de nuestro equipamiento:\n\nEquipo Polycom HDX 8000  para establecer conexión, ustedes en sus equipos deben habilitar el GateKeeper a nuestra IP 200.0.163.177 para luego marcar en fo','No se logra conectividad con Suthern Cross Group ya que la topologia de CorpBanca no permite salida directa a internet, por ende todos los sitios externos deben registrarse al VBP-ST de CorpBanca.\n',NULL,'soporte'),(103,'TMC-INC103',1,2,'2014-01-07 14:38:13','2014-01-07 13:39:29','2014-01-07 13:39:35',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','fcifuentes@touchmedia.cl','Bandera 76, piso 9, Santiago – Chile',0,'VBP-ST','54396801377B','54396801377B','\"Favor revisar los logs del VBP-ST y generar un informe, relacionado con un equipo del Consejo de Defensa del Estado (CDE) es de marca marca Aethra modelo X3. Por algún motivo no logra registrarse correctamente.\nNo es solución conectarse a través del VBP-E ya que el administrador no desea llamar/ser','El Equipo VBP-ST no se encuentra funcionando en su totalidad. Al no encontrarse 100% operativo no funcionara correctamente.\n',NULL,'soporte'),(104,'TMC-INC104',1,2,'2014-01-07 14:39:26','2014-01-07 13:40:45','2014-01-07 13:40:50',37,'Centro de Formación Técnica DUOC UC','No Existe','123123','123123','noexiste@duoc.com','Calle Dieciocho 102',0,'RMX 15000','xxxxxxx','xxxxxxx','El cliente borro las configuraciones de sistema del equipo RMX 1500, esto provoco alertas mayores los cuales debiamos solucionar.\n','Se realiza default factory a la RMX 1500 la cual volvio los flag al sistema y se incluyen dos flag mas los cuales sirven para la integracion con Lync. El equipo vuelve a estar operativo.\n',NULL,'soporte'),(105,'TMC-INC105',1,2,'2014-01-07 14:40:41','2014-01-07 13:41:31','2014-01-07 13:41:36',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','flineros@entel.cl','Bandera 76, piso 9, Santiago – Chile',0,'HDX 7000','xxxxxxx','xxxxxxx','Conexión con Access point Hospital Magallanes\n','Se entrega los pasos necesarios para la configuracion del router, el equipo queda operativo.\n',NULL,'soporte'),(106,'TMC-INC106',1,2,'2014-01-07 14:41:22','2014-01-07 13:42:57','2014-01-07 13:43:01',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','fcifuentes@touchmedia.cl','Bandera 76, piso 9, Santiago – Chile',321,'HDX7000','88130911BF3FCN','88130911BF3FCN','Favor revisar equipo en Instituto de Neurocirugía ,según antecedentes equipo debe estar desconfigurado. Agente en terreno probó punto de enlace  y con un PC funciona, pero con equipo de VC no.\n','El problema es netamente de red, el sistema no muestra error alguno, favor de verificar la configuraciones en la plataforma del establecimiento\n',NULL,'soporte'),(107,'TMC-INC107',1,2,'2014-01-07 14:42:47','2014-01-07 13:43:40','2014-01-07 13:43:45',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','fcifuentesd@touchmedia.cl','Bandera 76, piso 9, Santiago – Chile',0,'HDX 7000','xxxxxx','xxxxxx','Conexión con Access point Hospital Lota\n','Se entrega los pasos necesarios para la configuracion del router, el equipo queda operativo.\n',NULL,'soporte'),(108,'TMC-INC108',1,2,'2014-01-07 14:43:36','2014-01-07 13:45:14','2014-01-07 13:45:18',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','fcifuentes@touchmedia.cl','Bandera 76, piso 9, Santiago – Chile',319,'HDX7000','88130911BF90CN','88130911BF90CN','\"Se reiteró el ticket, favor ir a revisar a terreno de forma urgente.\nNo es problema de conectividad, se solicita: \n1.- Necesitamos las pruebas de conectividad realizadas hoy en terreno\n2. Se recomienda revisar la opción \"\"encapsulación de VLAN\"\" en el equipo, tal cual ocurrió en Hospital La Ligua (','El problema se encontraba en la Red, por lo conversado con Pablo, estaba bloqueando la MAC en el switch, en estos momentos el equipo está en funcionamiento, el cliente está en una videoconferencia.\n',NULL,'soporte'),(109,'TMC-INC109',1,2,'2014-01-08 22:36:54','2014-01-08 21:40:14','2014-01-08 21:40:19',50,'Inversiones y Turismo S.A. - DREAMS','No Existe','123123','123123','noexiste@casino.com','Avenida Presidente Riesco 5561 Of. 204',88,'HDX8000','8213170F9A80CG','8213170F9A80CG','Equipo no entrega audio local en videoconferencia','Se valida que problema se debe a falla de mesa de audio al cual esta conectado el codec de videoconferencia.\n\nSe conecta audio saliente de codec directamente a amplificadores de cliente hasta que cliente cambie su mesa de audio.',NULL,'soporte'),(110,'TMC-INC110',1,2,'2014-01-09 20:15:06','2014-01-09 19:16:01','2014-01-13 20:57:01',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','flineros@entel.cl','Bandera 76, piso 9, Santiago – Chile',0,'HDX 7000','xxxxx','xxxxx','Equipo con problemas de conectividad.','Se validan configuraciones en equipo y se detecta que problema es de redes.',NULL,'soporte'),(111,'TMC-INC111',1,0,'2014-01-10 18:35:07',NULL,NULL,3,'Instituto Profesional DUOC UC','Alexis Peña Maldonado','23540085','98299984','apenam@duoc.cl','Eliodoro Yañez 1595 Piso 11',47,'CMA4000','B027PW1','B027PW1','El equipo presenta problemas al levantar una videoconferencia, esta no levanta los 18 participantes, presenta un error con los recursos de la MCU del cual no deberia presentar, ya que RMX tiene 10 recursos en HD y los sitios se levantan en resolucion CIF. Polycom esta evaluando el problema.',NULL,NULL,NULL),(112,'TMC-INC112',1,2,'2014-01-13 14:19:20','2014-01-13 15:52:36','2014-01-13 15:52:42',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','flineros@entel.cl','Bandera 76, piso 9, Santiago – Chile',0,'Pizarra Smart','xxxxxxx','xxxxxxx','Se solicita técnico a revisar Pantalla Interactiva Smart Sala de Capacitación Hospital Salvador, no funciona el Touch solo proyecta.','Bastian realizo el soporte, efectivamente el modulo USB está en mal estado. El técnico realizo las pruebas correspondientes con el modulo, y el problema persiste. Favor de gestionar el cambio de esta pieza.',NULL,'soporte'),(113,'TMC-INC113',1,2,'2014-01-13 21:44:32','2014-01-13 20:56:35','2014-01-13 20:56:41',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','fcifuentes@touchmedia.cl','Bandera 76, piso 9, Santiago – Chile',0,'RSS','0004F29494EA','0004F29494EA','Mauricio Muñoz pide borrar videos del RSS y de RPMM.','Los archivos fueron borrados de las 2 plataformas.\ncg Aisen, cg Arauco, cg Magallanes, cg Valdivia, Sabado.',NULL,'soporte'),(114,'TMC-INC114',1,2,'2014-01-14 21:15:59','2014-01-14 20:18:02','2014-01-14 20:18:12',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','flineros@entel.cl','Bandera 76, piso 9, Santiago – Chile',0,'RMX 2000','VR2121230027','VR2121230027','Cliente solicita asistencia sobre creacion de conferencias en modalidad cascada.','Se da soporte a cliente sobre uso de equipo RMX en modalidad cascada',NULL,'soporte'),(115,'TMC-INC115',1,2,'2014-01-14 20:44:45','2014-01-14 20:18:58','2014-01-16 18:01:02',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','flineros@entel.cl','Bandera 76, piso 9, Santiago – Chile',0,'HDX 8000','xxxxx','xxxxx','Cliente solicita soporte para configuracion inalambrica de Carro Avanzado en Hospital Regional de Arica.','Se coordina configuraciones y pruebas para el dia 15/01 en la mañana',NULL,'soporte'),(116,'TMC-INC116',1,2,'2014-01-15 14:09:20','2014-02-03 13:26:36','2014-02-03 13:26:41',2,'Ministerio de Salud','Francisco Lineros C.','123123','957284132','flineros@entel.cl','Bandera 76, piso 9, Santiago – Chile',0,'RSS 4000','0004F29494FA','0004F29494FA','Cliente : Mauricio Muñoz','Equipo presenta problemas al momento de realizar descarga de contenido.\nSe realiza actualizacion de Software, se debe mantener equipo en pruebas por 72 Hrs. El equipo se encuentra operativo.',NULL,'soporte'),(117,'TMC-INC117',1,2,'2014-01-15 15:14:58','2014-01-15 14:18:31','2